const steps = $input.first().json.intermediateSteps || [];
const step = steps.find(s => s.action?.tool === "Agendar_Consulta");

if (!step) {
  return [{ json: { consultaCriada: false, tentouAgendar: false } }];
}

let obs;
try {
  obs = typeof step.observation === "string" ? JSON.parse(step.observation) : step.observation;
} catch (e) {
  return [{ json: { consultaCriada: false, tentouAgendar: true, motivoFalha: "erro_desconhecido", entrada: step.action.toolInput || null } }];
}
const resultado = Array.isArray(obs) ? obs[0] : obs;

if (!resultado || !resultado.sucesso) {
  return [{
    json: {
      consultaCriada: false,
      tentouAgendar: true,
      motivoFalha: (resultado && resultado.motivo) ? resultado.motivo : "erro_desconhecido",
      entrada: step.action.toolInput || null
    }
  }];
}

return [{
  json: {
    consultaCriada: true,
    eventoCalendarioId: resultado.eventoId,
    horarioInicio: resultado.inicio,
    horarioFim: resultado.fim
  }
}];

// nucleo.mjs
// Logica deterministica da trava de perguntas repetidas do Nucleo V3.1.
// Sem import e sem dependencias: o corpo e copiado para Code nodes do n8n (o "export " e removido).

// Classe de combinantes montada por codigo (sem escape barra-u nem caractere invisivel literal).
const MARCAS = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');

function limpar(texto) {
  return String(texto ?? '').normalize('NFD').replace(MARCAS, '').toLowerCase();
}

function ultimaPergunta(texto) {
  const t = String(texto ?? '').trim();
  const i = t.lastIndexOf('?');
  if (i < 0) return null;
  if (/[\p{L}\p{N}]/u.test(t.slice(i + 1))) return null;
  const antes = t.slice(0, i);
  const inicio = Math.max(antes.lastIndexOf('.'), antes.lastIndexOf('!'), antes.lastIndexOf('\n')) + 1;
  const pergunta = t.slice(inicio, i + 1).trim();
  return pergunta.length > 1 ? pergunta : null;
}

const TOPICOS = [
  ['judicial', /(process|judicial|execuc|citac|intimac|notificac|protest|negativ|cobranca)/],
  ['renegociacao', /(renegoci|negoci)/],
  ['documento', /(cnpj|cpf)/],
  ['valor', /(valor|quanto)/],
  ['outros_contratos', /outros (contratos|dividas)/],
  ['causa', /(por que|motivo|causa|faturamento)/],
  ['banco', /(banco|instituicao)/],
];

function topicoPergunta(pergunta) {
  const t = limpar(pergunta);
  for (const [nome, re] of TOPICOS) if (re.test(t)) return nome;
  return 'outro';
}

const NAO_RESPOSTA = new Set(['oi', 'ola', 'opa', 'e', 'ai', 'bom', 'dia', 'boa', 'tarde', 'noite', 'ok', 'okay', 'certo', 'blz', 'beleza', 'tudo', 'bem', 'obrigado', 'obrigada', 'valeu', 'hum', 'hmm', 'ahn']);

function naoRespondeu(mensagem) {
  const palavras = limpar(mensagem).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
  return palavras.every((p) => NAO_RESPOSTA.has(p));
}

function contarSeguidas(ultimasIa, topico) {
  const lista = Array.isArray(ultimasIa) ? ultimasIa : [];
  let n = 0;
  for (const msg of lista) {
    const p = ultimaPergunta(msg);
    if (p && topicoPergunta(p) === topico) n++;
    else break;
  }
  return n;
}

function estadoPergunta(ultimasIa) {
  const lista = Array.isArray(ultimasIa) ? ultimasIa : [];
  const p = ultimaPergunta(lista[0]);
  if (!p) return 'Sem pergunta pendente: sua última mensagem não terminou com uma pergunta (ou ainda não houve mensagem sua).';
  const n = contarSeguidas(lista, topicoPergunta(p));
  const vezes = n === 1 ? 'já foi feita 1 vez.' : 'já foi feita ' + n + ' vezes seguidas.';
  return 'PERGUNTA PENDENTE: sua última mensagem terminou com: «' + p + '»\n'
    + 'Essa pergunta (ou uma sobre o mesmo assunto) ' + vezes + '\n'
    + 'Se a mensagem atual da pessoa não respondeu a essa pergunta, não faça nenhuma pergunta nesta resposta: responda só ao que ela disse, em uma frase curta, e pare.';
}

function deveBloquearRepeticao({ saida, entrada, ultimasIa }) {
  const lista = Array.isArray(ultimasIa) ? ultimasIa : [];
  const nova = ultimaPergunta(saida);
  if (!nova) return false;
  const topico = topicoPergunta(nova);
  if (topico === 'outro') return false;
  if (naoRespondeu(entrada)) {
    // a pessoa nao respondeu: nao volta a um assunto ja perguntado nas ultimas 6 mensagens
    const recentes = lista.slice(0, 6).filter((m) => {
      const p = ultimaPergunta(m);
      return p !== null && topicoPergunta(p) === topico;
    }).length;
    return recentes >= 1;
  }
  return contarSeguidas(lista, topico) >= 2;
}

function primeiroNome(fatos) {
  const f = fatos && typeof fatos === 'object' ? fatos : {};
  const nome = String(f.nomeCompleto || f.nomeLead || f.nome || '').trim().split(/\s+/)[0] || '';
  return nome ? nome.charAt(0).toUpperCase() + nome.slice(1) : '';
}

function fallbackSemPergunta(entrada, fatos) {
  const t = limpar(entrada);
  let saudacao = 'Certo';
  if (t.includes('bom dia')) saudacao = 'Bom dia';
  else if (t.includes('boa tarde')) saudacao = 'Boa tarde';
  else if (t.includes('boa noite')) saudacao = 'Boa noite';
  else if (/^(oi|ola|opa)\b/.test(t)) saudacao = 'Oi';
  const nome = primeiroNome(fatos);
  return saudacao + (nome ? ', ' + nome : '') + '! Estou por aqui. Pode me contar com calma, no seu tempo.';
}

const bannedPatterns = [
  /cl[aá]usulas?\s+abusivas?/i,
  /revisional/i,
  /juros\s+abusivos/i,
  /capitaliza[cç][aã]o\s+irregular/i,
  /tarifas?\s+ilegal/i,
  /excesso\s+de\s+execu[cç][aã]o/i,
  /impenhorabilidade/i,
  /nulidades?/i,
  /direito\s+a\s+(desconto|redu[cç][aã]o)/i,
  /embargos/i
];

const item = $input.first().json;
let text = item.output || '';

const violated = bannedPatterns.some(p => p.test(text));
if (violated) {
  return [{
    json: {
      ...item,
      output: "Isso e uma analise que so o Dr. Santo consegue fazer olhando o contrato. Vou verificar um horario pra voces conversarem, pode ser?",
      guardrailTriggered: true,
      guardrailReason: "opiniao_juridica",
      guardrailOriginalOutput: text
    }
  }];
}

// Detecta vazamento de trace tecnico (chamada de ferramenta, JSON cru) na resposta.
const technicalLeakPatterns = [
  /calling\s+\w+\s+with\s+input/i,
  /\{"[a-zA-Z_]+"\s*:/,
  /function_calls|tool_call|intermediateStep/i
];
const hasTechnicalLeak = technicalLeakPatterns.some(p => p.test(text));
if (hasTechnicalLeak) {
  return [{
    json: {
      ...item,
      output: "Tive uma instabilidade agora ao confirmar isso. So um momento que eu reviso e te retorno.",
      guardrailTriggered: true,
      guardrailReason: "vazamento_tecnico",
      guardrailOriginalOutput: text
    }
  }];
}

// Valida qualquer data DD/MM mencionada no texto contra a janela real dos proximos 14 dias.
const validDatesDDMM = [];
for (let i = 0; i <= 14; i++) {
  validDatesDDMM.push($now.plus({ days: i }).setZone('America/Sao_Paulo').toFormat('dd/MM'));
}

const dateMatches = text.match(/\b(\d{1,2})\/(\d{1,2})\b/g) || [];
const normalizedMatches = dateMatches.map(m => {
  const [d, mo] = m.split('/');
  return d.padStart(2, '0') + '/' + mo.padStart(2, '0');
});
const hasBadDate = normalizedMatches.some(m => !validDatesDDMM.includes(m));

if (hasBadDate) {
  return [{
    json: {
      ...item,
      output: "Deixa eu confirmar certinho na agenda antes de seguir. Pode me dizer de novo o dia que prefere (ex: amanha, ou um dia da semana)?",
      guardrailTriggered: true,
      guardrailReason: "data_invalida_no_texto",
      guardrailOriginalOutput: text
    }
  }];
}

// Trava de pergunta repetida: se a Mayara voltar a perguntar o mesmo assunto sem a pessoa ter respondido,
// troca a resposta por uma sem pergunta (a pergunta pendente continua valendo).
let ultimasIa = [];
let entradaAtual = '';
let fatosAtuais = {};
try { ultimasIa = JSON.parse($('Calcular Lacunas').first().json.ultimasIa || '[]'); } catch (e) { ultimasIa = []; }
try { entradaAtual = String($('Montar Contexto').first().json.chatInput || ''); } catch (e) { entradaAtual = ''; }
try { fatosAtuais = JSON.parse($('Montar Contexto').first().json.fatosJson || '{}'); } catch (e) { fatosAtuais = {}; }
if (deveBloquearRepeticao({ saida: text, entrada: entradaAtual, ultimasIa })) {
  return [{
    json: {
      ...item,
      output: fallbackSemPergunta(entradaAtual, fatosAtuais),
      guardrailTriggered: true,
      guardrailReason: "pergunta_repetida",
      guardrailOriginalOutput: text
    }
  }];
}

return [{ json: item }];

